import { ACCEPTANCE_POLICY, AI_POLICY } from './acceptance-policy.js?v=20261024';
import { TERMS } from './contract-terms.js?v=20261024-policy';
export const LAUNCH_READY=true; // Published reception URL and final scope reviewed.
export const SERVICES=Object.freeze({
 short:{name:'素材を送るだけ・ショート動画1本編集',price:3000,scope:'完成60秒以内は税込3,000円〜。60秒を超える分は追加60秒ごと（端数は1枠）に税込1,000円。支給素材10分以内、カット・字幕・音量調整、修正1回。撮影・企画は別途。素材超過や複雑な編集は事前見積もりです。'},
 repair:{name:'Web・SNSの困ったところ1つ修正',price:3000,scope:'文章・画像の差し替えやプロフィール整備など1件。対象箇所と作業範囲を確認して総額を決定します。追加作業は事前見積もりです。'},
 website:{name:'新規Web・基本1ページ制作',price:10000,scope:'文章・写真支給を基本に、1ページ税込10,000円〜。2ページ20,000円〜、3ページ30,000円〜が基本目安。構成・ページの長さ・フォーム・予約・決済・ログイン機能・素材制作・ドメインやサーバー費は見積もり段階で別途明示します。ページ数だけで複雑な機能を含む総額は確定しません。'}
});
export function basePrice(d){if(d.service==='repair')return 3000;const value=d.service==='short'?d.seconds:d.pages;if(!/^\d+$/.test(String(value))||!Number.isSafeInteger(Number(value))||Number(value)<1)throw Error('完成秒数またはページ数を正の整数で入力してください。');if(d.service==='short')return 3000+Math.ceil(Math.max(0,Number(value)-60)/60)*1000;if(d.service==='website')return Number(value)*10000;throw Error('サービスを選択してください。');}
export const clean=v=>String(v??'').replace(/\r\n/g,'\n').trim();
const required=(d,keys)=>{for(const k of keys)if(!clean(d[k]))throw Error('必須項目を入力してください：'+k);};
const date=s=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(s)||!Number.isFinite(Date.parse(s))||new Date(s).toISOString().slice(0,10)!==s)throw Error('日付を確認してください。');return s;};
function validateCommon(d){if(!SERVICES[d.service])throw Error('サービスを選択してください。');if(d.category!=='general')throw Error('政治・選挙関係や判断未了のご依頼は通常注文できません。受託前確認へお進みください。');for(const v of Object.values(d))if(typeof v==='string'&&v.length>2000)throw Error('入力は各2,000文字以内にしてください。');}
export function validateInquiry(d){validateCommon(d);required(d,['description','name','reply']);if(!d.privacy||!d.inquiryOnly)throw Error('相談・見積依頼であることと個人情報の取扱いを確認してください。');return d;}
export function inquiryText(d){validateInquiry(d);return ['広報担当さんへの単発作業の相談・見積依頼（注文確定ではありません）','サービス：'+SERVICES[d.service].name,'依頼区分：一般事業','仕事内容・希望：'+d.description,'素材の有無：'+(d.materials||'未記入'),'希望納期（確約ではありません）：'+(d.deadlineWish||'未定'),'予算：'+(d.budget||'要相談'),'名前・屋号：'+d.name,'返信先：'+d.reply,'共有リンク：'+(d.materialLink||'受付後に相談'),'備考：パスワード・認証コードは送付しない。'].join('\n\n');}
export function validateDocument(d){validateCommon(d);if(!['estimate','contract','invoice','receipt'].includes(d.documentType))throw Error('書類を選択してください。');required(d,['number','customer','customerEmail','scope','exclusions','deadline','inspection','rights','payment','provider','providerSigner','providerEmail']);date(d.issueDate);date(d.deadline);if(!/^\d+$/.test(String(d.amount))||!Number.isSafeInteger(Number(d.amount))||Number(d.amount)<1||Number(d.amount)>10000000)throw Error('合意金額は1〜10,000,000円の整数で入力してください。');if(Number(d.amount)<basePrice(d))throw Error('総額が基本目安を下回っています。秒数・ページ数・金額を確認してください。');if(!/^\d+$/.test(String(d.revisions))||Number(d.revisions)>10)throw Error('修正回数を確認してください。');if(!d.reviewed)throw Error('内容を確認してください。');if(d.documentType!=='estimate'&&!d.agreed)throw Error('業務範囲・総額・納期・支払条件の合意を確認してください。');if(d.documentType==='contract'){required(d,['customerSigner','customerAddress']);}if(['invoice','receipt'].includes(d.documentType))required(d,['agreementReference']);if(d.documentType==='invoice'){date(d.paymentDue);required(d,['bankDetails']);}if(d.documentType==='receipt'){if(!d.paymentVerified)throw Error('実際の入金を確認するまで領収書は発行できません。');required(d,['paymentReference','paymentMethod']);date(d.paidOn);if(d.paidOn>d.issueDate)throw Error('入金日は発行日以前にしてください。');if(Number(d.paidAmount)!==Number(d.amount))throw Error('この領収書は全額入金専用です。実入金額と請求総額が一致しません。');}return d;}
const yen=n=>Number(n).toLocaleString('ja-JP')+'円';
export function documentContent(d){validateDocument(d);const labels={estimate:'単発業務 見積書',contract:'単発業務 委託契約書',invoice:'単発業務 請求書',receipt:'単発業務 領収書'},isReceipt=d.documentType==='receipt';
 const sections=[{title:'当事者・書類番号',paragraphs:['書類番号：'+d.number+'／作成日：'+d.issueDate,'宛名：'+d.customer+'／返信先：'+d.customerEmail,...(d.documentType==='contract'?['依頼者署名者：'+d.customerSigner+'／住所：'+d.customerAddress,'受託者住所：'+(d.providerAddress||'________________（契約時に記入）')]:[]),'発行者：'+d.provider+'／担当：'+d.providerSigner+'／連絡先：'+d.providerEmail,...(d.sample?['【見本】動作確認用です。実際の契約・請求・入金を証明するものではありません。']:[])]},
 {title:isReceipt?'受領金額・入金記録':'個別の業務範囲・総額',paragraphs:['サービス：'+SERVICES[d.service].name,...(d.service==='short'?['合意した完成尺：'+d.seconds+'秒']:d.service==='website'?['合意したページ数：'+d.pages+'ページ']:[]),'基本料金の目安（税込）：'+yen(basePrice(d))+'〜（追加費用を含む確定額は下記総額）','対象作業・納品物：'+d.scope,'含まない作業：'+d.exclusions,'金額（税込・総額）：'+yen(d.amount),'修正回数：'+d.revisions+'回。合意範囲の修正を対象とし、こちらの過失による修正は回数に数えず無料です。追加作業は実施前に別途見積もり・合意します。',...(isReceipt?['実入金額：'+yen(d.paidAmount),'入金日：'+d.paidOn+'／入金方法：'+d.paymentMethod,'入金確認記録：'+d.paymentReference,'上記金額を、合意済み単発業務の代金として受領しました。']:[])]},
 {title:'納品・検収・素材・支払',paragraphs:['合意した納期：'+d.deadline,'検収方法・確認期限：'+d.inspection,'素材の権利・許諾と成果物の利用範囲：'+d.rights,'合意した支払条件：'+d.payment,...(d.documentType==='invoice'?['支払期限：'+d.paymentDue,'振込先：'+d.bankDetails]:[]),'合意書面・確認記録：'+(d.agreementReference||'見積内容確認後に合意を記録します。'),'適格請求書発行事業者の登録番号はありません。適格請求書ではありません。','既存の初回お試し・月額プランの料金・本数・撮影等を自動適用しません。個別合意した上記範囲が対象です。']},
 {title:'受託条件・AI利用',paragraphs:[ACCEPTANCE_POLICY,AI_POLICY,'既存の締結済み契約は変更しません。この書類の生成だけで契約締結・メール送付・入金照合は行われません。',...(d.documentType==='estimate'?['見積書は相談に基づく条件案です。内容・納期・総額の合意前に着手しません。']:[])]}];
 const titles=new Set(['政治・選挙関係の受託条件','AIの制作補助と素材の取扱い','キャンセル・日程変更','公開承認・権限・素材','保管期間','契約・法令に関する確認']);
 return {documentTitle:(d.sample?'【見本】':'')+labels[d.documentType],sample:Boolean(d.sample),termsNotice:'本書の業務範囲・総額・納期・支払条件と、以下の共通条件を確認し、署名・同意の記録とともに保存してください。通常プランの金額・本数は本単発案件へ自動適用しません。受託条件・AI方針は2026年10月24日版。 https://local-koho.com/terms.html',type:d.documentType==='contract'?'contract':d.documentType,sections,terms:d.documentType==='contract'?TERMS.filter(t=>titles.has(t.title)):[],data:{...d,contractDate:d.issueDate}};
}
